To save and print answers in C language, you can write a simple program using the `FILE` and `printf` functions. Here's a basic example:

```c
#include <stdio.h>

int main() {
    FILE *file = fopen("output.txt", "w");
    if (file != NULL) {
        printf("Hello, World!\n");
        printf("This text is saved to output.txt.\n");
        fclose(file);
    } else {
        printf("Could not open output file.\n");
    }

    // To print the saved content
    file = fopen("output.txt", "r");
    if (file != NULL) {
        char c;
        while ((c = fgetc(file)) != EOF) {
            printf("%c", c);
        }
        fclose(file);
    } else {
        printf("Output file is empty.\n");
    }

    return 0;
}
```

